import java.util.*;

public class Main {
    static final String[] SCOPES = {"compile", "provided", "runtime", "test", "system", "import"};

    // 四种 classpath 上，各 scope 是否可见
    static boolean visible(String scope, String classpath) {
        switch (classpath) {
            case "compile":
                return scope.equals("compile") || scope.equals("provided") || scope.equals("system");
            case "test":
                return scope.equals("compile") || scope.equals("provided")
                        || scope.equals("runtime") || scope.equals("test") || scope.equals("system");
            case "runtime":
                return scope.equals("compile") || scope.equals("runtime") || scope.equals("system");
            case "packaged":
                return scope.equals("compile") || scope.equals("runtime");
            default:
                return false;
        }
    }

    public static void main(String[] args) {
        String[] cps = {"compile", "test", "runtime", "packaged"};
        System.out.println("=== scope visibility matrix (Y = visible on that classpath) ===");
        System.out.printf("%-10s", "scope");
        for (String c : cps) System.out.printf("%-10s", c);
        System.out.println();
        for (String s : SCOPES) {
            System.out.printf("%-10s", s);
            for (String c : cps) System.out.printf("%-10s", visible(s, c) ? "Y" : "-");
            System.out.println();
        }

        System.out.println();
        System.out.println("=== why 'provided' breaks at runtime ===");
        String[] deps = {"jackson:compile", "servlet-api:provided", "mysql-driver:runtime", "junit:test"};
        int cP = 0, tP = 0, rP = 0, pP = 0;
        for (String d : deps) {
            String scope = d.substring(d.indexOf(':') + 1);
            if (visible(scope, "compile")) cP++;
            if (visible(scope, "test")) tP++;
            if (visible(scope, "runtime")) rP++;
            if (visible(scope, "packaged")) pP++;
        }
        System.out.println("  jars on compile classpath : " + cP + " / " + deps.length);
        System.out.println("  jars on test classpath    : " + tP + " / " + deps.length);
        System.out.println("  jars on runtime classpath : " + rP + " / " + deps.length);
        System.out.println("  jars inside fat jar       : " + pP + " / " + deps.length);
        System.out.println("  NOTE: servlet-api is absent at runtime -> ClassNotFoundException if misused");
        System.out.println("  NOTE: junit is absent from the fat jar  -> test-only dependency is not shipped");
    }
}
